def find_order(base, modulus):
    if base == 0:
        return None
    if modulus == 1:
        return 1

    g = base % modulus
    if g == 0:
        return None # Should not happen for 3 mod 10000

    L = 1
    current_power = g
    while current_power != 1:
        current_power = (current_power * g) % modulus
        L += 1
        # Safety break, though theoretically it must divide phi(modulus)
        if L > modulus: 
            print("Order not found within modulus, something is wrong.")
            return None
    return L

L = find_order(3, 10000)
print(f"L = {L}")

def check_power(base, exponent, modulus):
    return pow(base, exponent, modulus)

# We know L must divide lambda(10000) = 500.
# We check divisors of 500 in increasing order.
divisors = [1, 2, 4, 5, 10, 20, 25, 50, 100, 125, 250, 500]
order = None

for L in divisors:
    if check_power(3, L, 10000) == 1:
        order = L
        break

print(f"The smallest divisor L of 500 such that 3^L = 1 (mod 10000) is L = {order}")
